'use strict' ;


const   p   =   s   =>   console.log( s ); // This is a tiny helper function for outputting strings.


/*
 * The main entry point for processing the input data.
 * The 'input' parameter contains the entire content read from standard input.
 */
function   Main (   input   )
{

  // The incoming 'input' string is broken down into an array of strings,
  // where each element corresponds to a line from the original input.
  input   =   input.split ( "\n" ) ;


  // From the very first line (input[0]), we extract the first space-separated token.
  // This token is assumed to be our number 'N'.
  var   N   =   input [ 0 ] .split ( " " ) [ 0 ] ;


  // Initialize a flag to track whether the digit '7' is found within the number 'N'.
  var   isSeven   =   false ;


  // Begin a loop that continues as long as the value of N is greater than 1.
  // This loop is designed to iterate through the digits of N from right to left.
  while   (   N   >   1   )
  {

    // Calculate the last digit of N using the modulo operator.
    var   num   =   N   %   10 ;

    // Check if the extracted digit is precisely '7'.
    if   (   num   ===   7   )
    {
      isSeven   =   true ; // If '7' is found, set the flag to true.
      break ; // Since '7' has been found, there's no need to check further digits; exit the loop.
    }

    // Remove the last digit from N by performing integer division.
    N   /=   10 ;
  }


  // After the loop, evaluate the 'isSeven' flag to determine the output.
  if   (   isSeven   )
  {
    p ( 'Yes' ) ; // If '7' was found, print "Yes".
  }
  else
  {
    p ( 'No' ) ; // Otherwise (if '7' was not found), print "No".
  }

}


